import {chromium} from 'playwright';
import {createServer} from 'node:http';
import {readFile} from 'node:fs/promises';
import {DatabaseSync} from 'node:sqlite';
import assert from 'node:assert/strict';
import {mockEnquiryDelivery} from './enquiry-test-fixture.mjs';
import {handle as intake} from '../workers/enquiries/index.mjs';
const sqlite=new DatabaseSync(':memory:');sqlite.exec(await readFile('workers/migrations/0001_enquiries.sql','utf8'));
const DB={prepare(sql){let args=[];const s={bind(...v){args=v;return s;},async first(){return sqlite.prepare(sql).get(...args)||null;},async run(){return {meta:{changes:Number(sqlite.prepare(sql).run(...args).changes)}};}};return s;},async batch(statements){sqlite.exec('BEGIN');try{const r=[];for(const s of statements)r.push(await s.run());sqlite.exec('COMMIT');return r;}catch(e){sqlite.exec('ROLLBACK');throw e;}}};
const server=createServer(async(req,res)=>{const p=new URL(req.url,'http://local').pathname;try{res.setHeader('Content-Type',p.endsWith('.js')?'text/javascript':p.endsWith('.css')?'text/css':p.endsWith('.svg')?'image/svg+xml':p.endsWith('.webp')?'image/webp':'text/html');res.end(await readFile('dist'+(p.endsWith('/')?p+'index.html':p)));}catch{res.statusCode=404;res.end();}});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port,browser=await chromium.launch();
try{
 const page=await browser.newPage({viewport:{width:390,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.route('**/*',r=>r.request().url().startsWith(base)?r.continue():r.abort());
 let fail=false;
 const submissions=await mockEnquiryDelivery(page,{handler:async payload=>fail?Response.json({error:'temporarily_unavailable'},{status:503}):intake(new Request('https://api.test/api/enquiries',{method:'POST',headers:{Origin:'https://raahhi.com','Content-Type':'application/json','CF-Connecting-IP':'192.0.2.100'},body:JSON.stringify(payload)}),{DB,TURNSTILE_SECRET:'test-only-secret'},async()=>Response.json({success:true,hostname:'raahhi.com',action:'enquiry'}))});
 const open=async path=>{await page.goto(base+path);await page.waitForFunction(()=>!document.querySelector('[data-currency-select]').disabled);};
 await open('/contact/');assert.equal(submissions.length,0,'Browsing does not transmit form fields');
 await page.locator('#contactPageForm button').click();assert.equal(submissions.length,0,'Invalid fields do not submit');
 for(const [id,value] of [['contactName','TEST integration <script>literal</script>'],['contactEmail','test@example.com'],['contactPhone','+919876543210'],['contactMessage','Please confirm my family travel dates.']])await page.locator('#'+id).fill(value);
 fail=true;await page.locator('#contactPageForm button').click();await page.getByRole('link',{name:'Continue directly on WhatsApp',exact:true}).waitFor();
 assert.equal(await page.locator('#contactPageDone').isVisible(),false,'Failed saves never show success');assert.equal(await page.locator('#contactName').inputValue(),'TEST integration <script>literal</script>','Failed saves retain fields');assert.equal(sqlite.prepare('SELECT count(*) AS n FROM enquiries').get().n,0);
 const retryId=submissions[0].requestId;fail=false;await page.locator('#contactPageForm button').click();await page.locator('#contactPageDone').waitFor({state:'visible'});assert.equal(submissions[1].requestId,retryId,'Retry reuses request ID');
 let row=sqlite.prepare('SELECT * FROM enquiries').get();assert.equal(row.kind,'contact');assert.equal(row.email,'test@example.com');assert.equal(row.page,'https://raahhi.com/contact/');assert((await page.locator('#contactMessagePreview').innerText()).includes(row.reference));assert.equal(await page.locator('#contactMessagePreview script').count(),0);
 await page.evaluate(()=>{const a=document.querySelector('[data-enquiry-actions="contactMessagePreview"] [data-enquiry-channel="whatsapp"]');prepareEnquiryLink(a,'contactMessagePreview','whatsapp');});const href=await page.locator('[data-enquiry-actions="contactMessagePreview"] [data-enquiry-channel="whatsapp"]').getAttribute('href');assert(new URL(href).searchParams.get('text').includes(row.reference),'WhatsApp message includes the persisted reference');
 await page.locator('#contactPageForm button').click();await page.locator('#contactPageDone').waitFor({state:'visible'});assert.equal(sqlite.prepare('SELECT count(*) AS n FROM enquiries').get().n,1,'Identical contact submission is idempotent');
 await open('/activities/dubai/evening-desert-safari/');await page.locator('#tourEnqGuests').fill('4');await page.evaluate(()=>enquireAboutProduct('activity','evening-desert-safari'));await page.locator('#callbackName').fill('TEST activity');await page.locator('#callbackPhone').fill('+919876543210');await page.locator('#callbackSubmit').click();await page.locator('#callbackDone').waitFor({state:'visible'});row=sqlite.prepare("SELECT * FROM enquiries WHERE kind='activity'").get();assert(row.product.includes('Evening Desert Safari'));assert(JSON.parse(row.details).some(([k,v])=>k==='Guests'&&v==='4'));assert.equal(await page.locator('#callbackName').inputValue(),'','Confirmed save clears completed modal fields');
 await open('/visas/singapore/');await page.evaluate(()=>openVisaEnquiry('singapore'));for(const [id,value] of [['visaEnqName','TEST visa'],['visaEnqEmail','test@example.com'],['visaEnqPhone','+919876543210']])await page.locator('#'+id).fill(value);for(const [id,value] of [['visaEnqNationality','IN'],['visaEnqResidence','AE'],['visaEnqPurpose','tourism']])await page.locator('#'+id).selectOption(value);await page.locator('#visaEnqForm button[type="submit"]').click();await page.locator('#visaEnqDone').waitFor({state:'visible'});row=sqlite.prepare("SELECT * FROM enquiries WHERE kind='visa'").get();assert.equal(row.product,'Singapore visa');assert(JSON.parse(row.details).some(([k,v])=>k==='Nationality'&&v==='India'));
 // A slow request cannot create a second submission or discard the pending modal.
 await page.locator('#visaEnquiryModal .modal-close').click();await page.evaluate(()=>openCallback());await page.locator('#callbackName').fill('TEST double click');await page.locator('#callbackPhone').fill('+919876543210');let release;const gate=new Promise(r=>release=r);const count=submissions.length;
 await page.route('https://raahhi-enquiries.asif-772.workers.dev/api/enquiries',async route=>{if(route.request().method()==='OPTIONS')return route.fallback();await gate;return route.fallback();});
 await page.locator('#callbackSubmit').click();await page.waitForFunction(()=>document.getElementById('callbackForm').dataset.saving==='true');await page.evaluate(()=>{document.getElementById('callbackForm').requestSubmit();closeModal('contactModal');});assert(await page.locator('#contactModal').isVisible(),'Pending save cannot be discarded');release();await page.locator('#callbackDone').waitFor({state:'visible'});assert.equal(submissions.length,count+1,'Double submit sends only one request');
 assert.deepEqual(errors,[]);console.log('PASS real client-to-Worker-to-SQLite flow: validation, failed-save recovery, idempotency, activity/visa context, confirmed references, WhatsApp handoff, escaping and duplicate prevention.');
}finally{await browser.close();server.close();sqlite.close();}
